create extension if not exists pgcrypto;
create table if not exists products(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,category text not null,description text,price_inr int not null,active boolean default true,featured boolean default false,metadata jsonb default '{}'::jsonb,created_at timestamptz default now());
create table if not exists orders(id uuid primary key default gen_random_uuid(),order_code text unique not null,email text not null,product_slug text not null,amount_inr int not null,status text default 'created',razorpay_order_id text,razorpay_payment_id text,razorpay_signature text,payload jsonb default '{}'::jsonb,download_url text,created_at timestamptz default now(),paid_at timestamptz);
create table if not exists prompt_products(id uuid primary key default gen_random_uuid(),slug text unique not null,title text not null,category text not null,teaser text not null,prompt_text text not null,price_inr int not null,active boolean default true,created_at timestamptz default now());
create table if not exists business_leads(id uuid primary key default gen_random_uuid(),name text,business_name text,email text,phone text,budget text,request text,created_at timestamptz default now());
alter table products enable row level security; alter table orders enable row level security; alter table prompt_products enable row level security; alter table business_leads enable row level security;
create policy "public active products" on products for select using(active=true);
create policy "public active prompts" on prompt_products for select using(active=true);
insert into products(slug,name,category,description,price_inr,featured,metadata) values('book-10','Book Studio — 10 Pages','Books','Premium personal book.',9,true,'{"pages":10}'),('book-20','Book Studio — 20 Pages','Books','Premium short book.',19,true,'{"pages":20}'),('book-30','Book Studio — 30 Pages','Books','Complete short edition.',29,false,'{"pages":30}'),('book-50','Book Studio — 50 Pages','Books','Extended edition.',49,false,'{"pages":50}'),('book-75','Book Studio — 75 Pages','Books','Long edition.',69,false,'{"pages":75}'),('book-100','Book Studio — 100 Pages','Books','Full edition.',89,true,'{"pages":100}') on conflict(slug) do nothing;
insert into prompt_products(slug,title,category,teaser,prompt_text,price_inr) values('wedding-luxe','Wedding Luxe Portrait','Wedding','Cinematic luxury wedding direction.','Create a premium cinematic wedding portrait from the supplied photo. Preserve identity and facial structure. Elegant Indian wedding styling, luxury venue, realistic skin, refined editorial lighting and sophisticated composition.',9),('birthday-glow','Birthday Glow Poster','Birthday','Premium birthday creative direction.','Create a premium birthday celebration poster using the supplied photo. Preserve identity, realistic details, elegant lighting and social-media-ready composition.',9),('business-hero','Business Hero Advertisement','Business','Commercial advertising direction.','Create a premium commercial advertisement for the supplied business with strong product hierarchy, luxury lighting, headline area, offer area and CTA.',9) on conflict(slug) do nothing;
